/**
 * Project-owned Supabase helpers.
 *
 * `src/integrations/supabase/client.ts` and `types.ts` are generated by Lovable
 * Cloud and are rewritten whenever the backend changes. The course platform's
 * own helpers used to live inside `client.ts` and were wiped by the first
 * regeneration; they live here instead, where nothing overwrites them.
 *
 * `db` is the same client the generated module exports, viewed without the
 * generated row types. The course tables exist only as migrations in
 * `supabase/migrations/` for now (docs/COURSE_PLATFORM_SETUP.md §2), so the
 * generated Database type has no tables in it yet — without this view every
 * `.from("...")` call is a compile error even though the query is correct.
 * Once the migrations are applied and the types regenerate, callers can go
 * back to the typed client and this export can be removed.
 */
import type { SupabaseClient } from "@supabase/supabase-js";
import { supabase } from "@/integrations/supabase/client";

const url = import.meta.env.VITE_SUPABASE_URL ?? "";
const publishableKey = import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY ?? "";

/** False only when the backend has not been provisioned at all. */
export const isBackendConfigured = Boolean(url && publishableKey);

/**
 * A permissive stand-in for the generated Database type. `.from("...")` only
 * accepts table names that appear in that type, and the course tables are not
 * in it yet — so without this, every query in the course platform is a compile
 * error even though the query itself is correct.
 */
type LooseTable = {
  Row: Record<string, unknown>;
  Insert: Record<string, unknown>;
  Update: Record<string, unknown>;
  Relationships: [];
};

type LooseDatabase = {
  public: {
    Tables: Record<string, LooseTable>;
    Views: Record<string, never>;
    Functions: Record<string, never>;
    Enums: Record<string, never>;
    CompositeTypes: Record<string, never>;
  };
};

/** The generated client, viewed without the (currently empty) row types. */
export const db = supabase as unknown as SupabaseClient<LooseDatabase>;

export function requireSupabase(): SupabaseClient<LooseDatabase> {
  if (!isBackendConfigured) {
    throw new Error(
      "The course backend is not connected yet. Enable Lovable Cloud on this project to provision it.",
    );
  }
  return db;
}

/**
 * Resolve a stored "bucket/key" path in the PUBLIC bucket to a URL.
 *
 * Only ever called with course-public paths (trailers, poster frames). Gated
 * media has no client-side URL by design — it goes through get-media-url.
 */
export function publicStorageUrl(storedPath: string | null | undefined): string | null {
  if (!storedPath || !url) return null;
  if (/^https?:\/\//i.test(storedPath)) return storedPath;
  if (!storedPath.startsWith("course-public/")) return null;
  return `${url.replace(/\/$/, "")}/storage/v1/object/public/${storedPath}`;
}

/** Invoke an edge function and unwrap its JSON, normalising the error shape. */
export async function callFunction<T>(
  name: string,
  body: Record<string, unknown>,
): Promise<T> {
  const client = requireSupabase();
  const { data, error } = await client.functions.invoke(name, { body });
  if (error) throw error;
  if (data && typeof data === "object" && "error" in data) {
    throw new Error(String((data as { error: unknown }).error));
  }
  return data as T;
}
